package com.josephison.fiatlux.realm;

import com.josephison.fiatlux.FiatLux;
import com.josephison.fiatlux.world.cosmos.Planet;
import com.josephison.fiatlux.world.cosmos.PlanetType;
import net.minecraft.core.registries.Registries;
import net.minecraft.resources.ResourceKey;
import net.minecraft.world.level.Level;
import org.jetbrains.annotations.Nullable;

import java.util.List;

/**
 * The Realm Forge's pre-registered dimension pool (design doc section 2, realm/). Each created planet is bound to
 * a slot (its creation order) and its world is generated by {@link PlanetChunkGenerator} from the
 * slot's settings. Pool dimensions are declared in data/fiatlux/dimension/planet_N.json, so a
 * world can host up to {@link #SIZE} enterable planets without runtime dimension hacks.
 */
public final class RealmPool {
    public static final int SIZE = 16;

    /** Generation settings of a bound slot, published for worldgen threads. */
    public record Settings(String name, PlanetType type, long seed, double gravity) {}

    private static final Settings[] SLOTS = new Settings[SIZE];

    private RealmPool() {}

    public static ResourceKey<Level> dimension(int slot) {
        return ResourceKey.create(Registries.DIMENSION, FiatLux.id("planet_" + slot));
    }

    /** The pool slot of a dimension, or -1 if it is not a created world. */
    public static int slotOf(ResourceKey<Level> dim) {
        if (!dim.location().getNamespace().equals(FiatLux.MODID)) return -1;
        String p = dim.location().getPath();
        if (!p.startsWith("planet_")) return -1;
        try {
            int s = Integer.parseInt(p.substring(7));
            return s >= 0 && s < SIZE ? s : -1;
        } catch (NumberFormatException e) {
            return -1;
        }
    }

    @Nullable
    public static Settings get(int slot) {
        return slot >= 0 && slot < SIZE ? SLOTS[slot] : null;
    }

    public static synchronized void publish(List<Planet> planets) {
        for (int i = 0; i < SIZE; i++) {
            if (i < planets.size()) {
                Planet p = planets.get(i);
                SLOTS[i] = new Settings(p.name, p.type, p.id.getMostSignificantBits() ^ p.id.getLeastSignificantBits(), p.gravity);
            } else {
                SLOTS[i] = null;
            }
        }
    }

    /** For tests: bind a slot directly. */
    public static synchronized void bind(int slot, Settings s) {
        SLOTS[slot] = s;
    }
}
